sqlLexer::sqlLexer(CharStream *input) : Lexer(input) {
  sqlLexer::initialize();
  _interpreter = new atn::LexerATNSimulator(this, *sqllexerLexerStaticData->atn, sqllexerLexerStaticData->decisionToDFA, sqllexerLexerStaticData->sharedContextCache);
}

sqlLexer::~sqlLexer() {
  delete _interpreter;
}

